// Cruza clientes (vindos do Webhook) com as opcoes do CSV e gera mensagens estaticas por perfil.
const webhook = $('Webhook').first().json;
const body = webhook.body;
const clientes = Array.isArray(body) ? body : (body.clientes || []);

const norm = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

// ---- parse do CSV (aceita , ou ;) ----
const csvText = String($input.first().json.data || '').replace(/^\uFEFF/, '');
const linhas = csvText.split(/\r?\n/).filter((l) => l.trim() !== '');
const delim = (linhas[0] || '').split(';').length > (linhas[0] || '').split(',').length ? ';' : ',';
const cabecalho = (linhas[0] || '').split(delim).map((h) => norm(h));
const opcoes = linhas.slice(1).map((l) => {
  const cols = l.split(delim).map((c) => c.trim());
  const obj = {};
  cabecalho.forEach((h, i) => (obj[h] = cols[i]));
  return obj;
});

const colPerfil = cabecalho.find((h) => h.includes('perfil')) || cabecalho[0];
const colNome = cabecalho.find((h) => /(nome|produto|investimento|ativo|opcao)/.test(h) && h !== colPerfil) || cabecalho[1];
const colRisco = cabecalho.find((h) => h.includes('risco'));
const colRet = cabecalho.find((h) => /(rent|retorno)/.test(h));

const descrever = (o) => {
  let t = o[colNome];
  const extras = [];
  if (colRet && o[colRet]) extras.push('rentabilidade ' + o[colRet]);
  if (colRisco && o[colRisco]) extras.push('risco ' + o[colRisco]);
  return extras.length ? `${t} (${extras.join(', ')})` : t;
};

// ---- templates estaticos (MVP) ----
const templates = {
  conservador: (c, lista) => `Ola, ${c.nome}! Com seu saldo de ${c.saldo}, o foco e seguranca e previsibilidade. Para o seu perfil conservador, sugerimos renda fixa: ${lista}.`,
  moderado: (c, lista) => `Ola, ${c.nome}! Com seu saldo de ${c.saldo}, o ideal e equilibrar. Para o seu perfil moderado, sugerimos um mix de renda fixa e variavel: ${lista}.`,
  arrojado: (c, lista) => `Ola, ${c.nome}! Com seu saldo de ${c.saldo}, voce pode buscar mais retorno. Para o seu perfil arrojado, sugerimos mais exposicao a acoes e renda variavel: ${lista}.`
};

return clientes.map((c) => {
  const perfil = norm(c.perfil);
  const doPerfil = opcoes.filter((o) => norm(o[colPerfil]) === perfil);
  const lista = doPerfil.length ? doPerfil.map(descrever).join('; ') : 'consulte nosso time para opcoes sob medida';
  const gerar = templates[perfil] || ((cl, l) => `Ola, ${cl.nome}! Temos opcoes de investimento para voce: ${l}.`);
  return {
    json: {
      nome: c.nome,
      email: c.email,
      saldo: c.saldo,
      perfil: c.perfil,
      mensagem: gerar(c, lista)
    }
  };
});
